CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'عضو جديد', username text NOT NULL UNIQUE CHECK (username ~ '^[a-zA-Z0-9_]{3,30}$'), bio text NOT NULL DEFAULT '' CHECK (length(bio) <= 280), avatar_path text, banner_path text, joined_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon, authenticated;
GRANT UPDATE (display_name, username, bio, avatar_path, banner_path) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_public_read ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY profiles_owner_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid() AND (avatar_path IS NULL OR split_part(avatar_path, '/', 1) = auth.uid()::text) AND (banner_path IS NULL OR split_part(banner_path, '/', 1) = auth.uid()::text));
CREATE TABLE public.member_xp (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, xp integer NOT NULL DEFAULT 0 CHECK (xp >= 0));
GRANT SELECT ON public.member_xp TO anon, authenticated;
GRANT ALL ON public.member_xp TO service_role;
ALTER TABLE public.member_xp ENABLE ROW LEVEL SECURITY;
CREATE POLICY xp_public_read ON public.member_xp FOR SELECT TO anon, authenticated USING (true);
CREATE FUNCTION public.create_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, username) VALUES (NEW.id, coalesce(nullif(NEW.raw_user_meta_data->>'full_name', ''), 'عضو جديد'), 'member_' || replace(NEW.id::text, '-', '')); INSERT INTO public.member_xp(user_id) VALUES (NEW.id); RETURN NEW; END $$;
CREATE TRIGGER on_auth_member_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_member_profile();
CREATE TABLE public.communities (id text PRIMARY KEY, name jsonb NOT NULL, description jsonb NOT NULL, icon text NOT NULL DEFAULT 'Users', created_by uuid);
GRANT SELECT ON public.communities TO anon, authenticated;
GRANT INSERT ON public.communities TO authenticated;
GRANT ALL ON public.communities TO service_role;
ALTER TABLE public.communities ENABLE ROW LEVEL SECURITY;
CREATE POLICY communities_public_read ON public.communities FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY communities_rank_create ON public.communities FOR INSERT TO authenticated WITH CHECK (created_by = auth.uid() AND EXISTS (SELECT 1 FROM public.member_xp WHERE user_id = auth.uid() AND xp >= 50));
CREATE TABLE public.community_memberships (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, community_id text REFERENCES public.communities(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, community_id));
GRANT SELECT, INSERT, DELETE ON public.community_memberships TO authenticated;
GRANT ALL ON public.community_memberships TO service_role;
ALTER TABLE public.community_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_owner_read ON public.community_memberships FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY membership_owner_join ON public.community_memberships FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY membership_owner_leave ON public.community_memberships FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.posts (id text PRIMARY KEY, author_id uuid, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.posts TO anon, authenticated;
GRANT ALL ON public.posts TO service_role;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY posts_public_read ON public.posts FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.saved_tools (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, tool_id text NOT NULL, PRIMARY KEY(user_id, tool_id));
GRANT SELECT, INSERT, DELETE ON public.saved_tools TO authenticated;
GRANT ALL ON public.saved_tools TO service_role;
ALTER TABLE public.saved_tools ENABLE ROW LEVEL SECURITY;
CREATE POLICY saved_owner_read ON public.saved_tools FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY saved_owner_insert ON public.saved_tools FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY saved_owner_delete ON public.saved_tools FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.platform_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT jsonb_build_object('posts', (SELECT count(*) FROM public.posts), 'members', (SELECT count(DISTINCT user_id) FROM public.community_memberships), 'communities', (SELECT count(*) FROM public.communities), 'communityMembers', coalesce((SELECT jsonb_object_agg(community_id, total) FROM (SELECT community_id, count(*) AS total FROM public.community_memberships GROUP BY community_id) m), '{}'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.platform_stats() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.platform_stats() TO anon, authenticated, service_role;
CREATE POLICY profile_images_owner_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'profile-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY profile_images_owner_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'profile-images' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('jpg', 'jpeg', 'png', 'webp'));
CREATE POLICY profile_images_owner_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'profile-images' AND (storage.foldername(name))[1] = auth.uid()::text);